## Code Example
```javascript
// pseudo mapping
function mapEvent(event, registry) {
  const latest = registry.latestFor(event.type);
  const v = event.schema_version ?? 1;
  if (v < latest.version) {
    return migrate(event, v, latest.version);
  }
  return event;
}
```

